import { coinNames, coinDarkVersions, type CoinName } from '../../icons/coin-names';
import './CoinIcon.css';

/* The Figma "Coin" set (src/icons/coin, generated by `npm run icons`). Not inlined into the bundle:
   the page loads only the icons it shows. */
const files = import.meta.glob<string>('../../icons/coin/*.svg', { eager: true, query: '?no-inline', import: 'default' });
const urlOf = (file: string) => files[`../../icons/coin/${file}.svg`];

export { coinNames, type CoinName };

export type CoinIconProps = {
  /** Figma Name in lower case with hyphens: "Bitcoin (BTC)" → `bitcoin-btc` */
  name: CoinName;
  /** Size in px. The guidelines use 20 and 24, matched to the component and text size. */
  size?: 20 | 24;
  /** Accessible name, such as "Bitcoin". Leave it out when the coin name is written next to the icon. */
  label?: string;
  className?: string;
};

/**
 * A cryptocurrency, token or currency logo in its own colours (Figma "Coin").
 * Coins on a black disc have a dark-theme version with black and white swapped (Figma has none), so they
 * don't disappear on dark. Both pictures are in the page; CSS shows the one for the theme, and a lazy image
 * that is hidden is never downloaded.
 */
export function CoinIcon({ name, size = 24, label, className = '' }: CoinIconProps) {
  const img = (file: string, theme?: 'light' | 'dark') => (
    <img
      className={`grg-coin-icon ${theme ? `grg-coin-icon--on-${theme}` : ''} ${className}`}
      src={urlOf(file)}
      width={size}
      height={size}
      alt={label ?? ''}
      loading="lazy"
      decoding="async"
    />
  );
  if (!coinDarkVersions.includes(name)) return img(name);
  return (
    <>
      {img(name, 'light')}
      {img(`${name}-dark`, 'dark')}
    </>
  );
}
